const original = $json.entrada_original ?? $json.original_input ?? $json.chatInput ?? '';

const raw =
  $json.text ??
  $json.output ??
  $json.response ??
  $json.producción ??
  '';

let d;

try {
  d = JSON.parse(
    String(raw)
      .replace(/^```json\s*/i, '')
      .replace(/```$/i, '')
      .trim()
  );
} catch (e) {
  d = {};
}

const intentValue = d.intent ?? d.intención ?? 'UNKNOWN';
const confidenceValue = d.confidence ?? d.confianza ?? 0;
const riskValue = d.risk ?? d.riesgo ?? 'HIGH';

const allowed = ['BILLING', 'TECH_SUPPORT', 'SALES', 'UNKNOWN'];

return [{
  json: {
    original_input: original,
    intent: allowed.includes(intentValue) ? intentValue : 'UNKNOWN',
    confidence: Math.max(0, Math.min(1, Number(confidenceValue))),
    risk: ['LOW', 'MEDIUM', 'HIGH'].includes(riskValue) ? riskValue : 'HIGH'
  }
}];

const chat = $('When chat message received').first().json;
const agent = $input.first().json;

const respuesta =
  agent.respuesta ??
  agent.output ??
  agent.text ??
  agent.response ??
  '';

function readCtx() {
  const names = ['Contexto Memoria Existente', 'Editar campos4'];

  for (const name of names) {
    try {
      const row = $(name).first().json;

      if (row) {
        const sessionId = row.Session_ID ?? row['ID de sesión'];
        const userName = row.user_name ?? row['nombre de usuario'];
        const status = row.status ?? row['estado'];
        const summary = row.last_summary ?? row['último_resumen'];
        const count = row.message_count ?? row['mensaje_contador'];

        if (
          sessionId ||
          userName ||
          summary !== undefined ||
          count !== undefined
        ) {
          return {
            Session_ID: sessionId,
            user_name: userName,
            status: status,
            last_summary: summary,
            message_count: count
          };
        }
      }
    } catch (e) {}
  }

  return {
    Session_ID: chat.sessionId,
    user_name: 'Usuario nuevo',
    status: 'nuevo',
    last_summary: 'Primera interacción, sin historial previo.',
    message_count: 0
  };
}

const ctx = readCtx();

const count = Number(ctx.message_count || 0) + 1;

return [
  {
    json: {
      Session_ID: chat.sessionId,
      user_name: ctx.user_name || 'Usuario',
      status: 'activo',
      last_summary: ctx.last_summary || 'Sin resumen previo.',
      message_count: count,
      chatInput: chat.chatInput || '',
      respuesta_agente: respuesta,
      output: respuesta
    }
  }
];

