const prev = $('Incrementar Contador').first().json;
const raw = $input.first().json;

let summaryObj = raw.output;

if (!summaryObj || typeof summaryObj !== 'object') {
  summaryObj = {
    asunto_principal: raw.asunto_principal || 'Conversación general',
    puntos_clave: Array.isArray(raw.puntos_clave)
      ? raw.puntos_clave
      : [String(raw.puntos_clave || 'Sin puntos')],
    accion_requerida: raw.accion_requerida || 'ninguna'
  };
}

return [{
  json: {
    Session_ID: prev.Session_ID,
    user_name: prev.user_name,
    status: 'resumido',
    last_summary: JSON.stringify(summaryObj),
    message_count: 0,
    output: prev.respuesta_agente
  }
}];

