const src = $('Set - Limpiar payload Email').first().json;

const raw = $json.text ?? $json.output ?? $json.response ?? '';

let d;

try {
  d = JSON.parse(
    String(raw)
      .replace(/^```json\s*/i, '')
      .replace(/```$/i, '')
      .trim()
  );
} catch (e) {
  d = {
    intent: 'UNKNOWN',
    confidence: 0,
    risk: 'HIGH',
    draft_body: 'Requiere revisión humana.'
  };
}

return [{
  json: {
    ...src,
    intent: d.intent ?? 'UNKNOWN',
    confidence: Number(d.confidence ?? 0),
    risk: d.risk ?? 'HIGH',
    draft_body: d.draft_body ?? ''
  }
}];
